#!/usr/bin/env python3
"""Real Tesseract import of the flattened browser export, native overlays remain editable."""
import argparse,pathlib,json,subprocess,os
p=argparse.ArgumentParser();p.add_argument('video');p.add_argument('--output',default='out/adapter.tsrct');a=p.parse_args();cli=os.environ.get('TSRCT',str(pathlib.Path.home()/'.local/share/Tesseract/bin/tsrct'))
def run(args):return json.loads(subprocess.check_output([cli]+args))
project=pathlib.Path(a.output);work=project.with_suffix('.json');run(['project','create','--project',str(project)]);meta=run(['project','import-video','--project',str(project),'--file',str(pathlib.Path(a.video).resolve()),'--asset-id','browser-render']);run(['project','checkout','--project',str(project),'--output',str(work)]);d=json.load(open(work));duration=meta['durationMs'];w=meta['width'];h=meta['height'];d['dimensions']={'width':w,'height':h};d['duration']=duration/1000
range={'start':0,'duration':duration};d['composition']['layers'].append({'type':'Video','id':1,'name':'Flattened deterministic Canvas render','playback':{'type':'windowed','inputRange':range,'mapping':{'type':'linear','input':range,'output':range},'inputOffsetMs':0},'sourceRange':range,'sourceIntrinsicDuration':duration,'volume':1,'transform':{'anchorPoint':[0,0],'position':[0,0],'scale':[100,100],'rotation':0,'opacity':100},'source':{'assetId':'browser-render','fit':'contain','sourceRect':{'x':0,'y':0,'width':w,'height':h}}});work.write_text(json.dumps(d,indent=2));run(['project','commit','--project',str(project),'--file',str(work)]);print(project)
